const viewmodel = options.contextData.viewmodel;
const resultSettings = {
	hidden: true
};

if (viewmodel.IsEqualEditableLevel(options.contextData.documentationEnums.EditLevels.FullAllow)) {
	const currentSelectedList = viewmodel.GetSelectedItems();

	if (currentSelectedList.length === 1) {
		const currentSelectedItem = currentSelectedList[0];
		if (currentSelectedItem.is('ArasListXmlSchemaElement') || (currentSelectedItem.is('ArasListItemXmlSchemaElement') && currentSelectedItem.List())) {
			resultSettings.hidden = false;
		}
	}
}

return resultSettings;
